body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }
h2 { font-size: 16px; margin: 0 0 8px; }

.suite {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-bottom: 12px;
  border-left: 4px solid #e4e4e7;
}

.suite.ok { border-left-color: #0a7a35; }
.suite.bad { border-left-color: #b91c1c; }

.suite ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.suite li {
  padding: 4px 0;
  font-size: 14px;
  border-bottom: 1px solid #f4f4f5;
}

.suite li:last-child { border-bottom: none; }

.suite li.ok { color: #14532d; }
.suite li.bad { color: #991b1b; }

// Shop.mn-ий тооцооллын функцүүд. Энэ файлыг өөрчлөх шаардлагагүй —
// таны ажил бол эдгээрийг ШАЛГАХ тест бичих.

function cartTotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

function applyDiscount(total, code) {
  if (code === "ШИНЭ10") return Math.round(total * 0.9);
  if (code === "ЗУН20") return Math.round(total * 0.8);
  return total;
}

function validateOrder(order) {
  if (!order.items || order.items.length === 0) {
    throw new Error("Сагс хоосон байна");
  }

  if (!/^\d{8}$/.test(order.phone || "")) {
    throw new Error("Утасны дугаар буруу");
  }

  return true;
}

window.SHOP = { cartTotal, applyDiscount, validateOrder };

// Shop.mn-ий тестүүд.
// it("тайлбар", () => { expect(...).toBe(...); });

function tests() {
  it("хоёр барааны нийлбэрийг тоо ширхэгээр нь бодно", () => {
    const items = [
      { name: "Дээл", price: 100000, quantity: 2 },
      { name: "Малгай", price: 45000, quantity: 1 },
    ];
    expect(cartTotal(items)).toBe(245000);
  });

  it("нэг ширхэг бараа өөрийнхөө үнэтэй тэнцэнэ", () => {
    expect(cartTotal([{ name: "Малгай", price: 45000, quantity: 1 }])).toBe(45000);
  });

  // энд бичнэ үү
}

window.tests = tests;

// Жижиг тест ажиллуулагч. Энэ файлыг өөрчлөх шаардлагагүй.
//
// Таны тестийг ХОЁР удаа ажиллуулна:
//   1) зөв хувилбар дээр — бүгд ДАВАХ ёстой,
//   2) санаатай эвдэрсэн хувилбар бүр дээр — дор хаяж нэг нь УНАХ ёстой.
// Унахгүй бол тэр тест алдааг барьж чадахгүй гэсэн үг.

const MUTANTS = {
  noQuantity: {
    label: "Тоо ширхэгээр үржүүлэхээ мартсан",
    fn: "cartTotal",
    impl: (items) => items.reduce((sum, item) => sum + item.price, 0),
  },
  emptyOne: {
    label: "Хоосон сагсанд 0-ийн оронд 1 буцаадаг",
    fn: "cartTotal",
    impl: (items) => (items.length === 0 ? 1 : SHOP.cartTotal(items)),
  },
};

const output = document.getElementById("output");

let current = null;

function it(name, body) {
  const result = { name: name, passed: true, message: null };

  try {
    body();
  } catch (problem) {
    result.passed = false;
    result.message = problem.message;
  }

  current.cases.push(result);
  if (!result.passed) current.failed += 1;
  current.total += 1;
}

function expect(actual) {
  return {
    toBe(expected) {
      if (!Object.is(actual, expected)) {
        throw new Error("хүлээсэн " + JSON.stringify(expected) + ", гарсан " + JSON.stringify(actual));
      }
    },
    toEqual(expected) {
      if (JSON.stringify(actual) !== JSON.stringify(expected)) {
        throw new Error("хүлээсэн " + JSON.stringify(expected) + ", гарсан " + JSON.stringify(actual));
      }
    },
    toThrow(message) {
      if (typeof actual !== "function") {
        throw new Error("toThrow нь функц хүлээдэг: expect(() => ...).toThrow()");
      }
      let thrown = null;
      try {
        actual();
      } catch (problem) {
        thrown = problem;
      }
      if (!thrown) throw new Error("алдаа шидэх ёстой байсан ч шидсэнгүй");
      if (message !== undefined && !String(thrown.message).includes(message)) {
        throw new Error("алдааны мессежид «" + message + "» байх ёстой, гарсан: " + thrown.message);
      }
    },
  };
}

window.it = it;
window.expect = expect;

function runSuite(label) {
  current = { label: label, cases: [], failed: 0, total: 0 };
  try {
    tests();
  } catch (problem) {
    current.cases.push({ name: "(тест ажиллуулахад алдаа)", passed: false, message: problem.message });
    current.failed += 1;
    current.total += 1;
  }
  return current;
}

function useImplementation(overrides) {
  window.cartTotal = overrides.cartTotal || SHOP.cartTotal;
  window.applyDiscount = overrides.applyDiscount || SHOP.applyDiscount;
  window.validateOrder = overrides.validateOrder || SHOP.validateOrder;
}

function panel(title, className, lines) {
  const box = document.createElement("section");
  box.className = "suite " + className;

  const heading = document.createElement("h2");
  heading.textContent = title;
  box.append(heading);

  const list = document.createElement("ul");
  for (const line of lines) {
    const li = document.createElement("li");
    li.className = line.ok ? "ok" : "bad";
    li.textContent = (line.ok ? "✓ " : "✗ ") + line.text;
    list.append(li);
  }
  box.append(list);
  output.append(box);
}

(function () {
  window.TEST_REPORT = {};

  // 1. Зөв хувилбар дээр.
  useImplementation({});
  const correct = runSuite("correct");
  window.TEST_REPORT.correct = { failed: correct.failed, total: correct.total };

  panel(
    "Зөв хувилбар — " + (correct.total - correct.failed) + "/" + correct.total,
    correct.failed === 0 ? "ok" : "bad",
    correct.cases.map((c) => ({ ok: c.passed, text: c.name + (c.passed ? "" : " — " + c.message) })),
  );

  // 2. Эвдэрсэн хувилбар бүр дээр: тестүүд алдааг барих ёстой.
  const caught = [];
  for (const key of Object.keys(MUTANTS)) {
    const mutant = MUTANTS[key];
    useImplementation({ [mutant.fn]: mutant.impl });
    const run = runSuite(key);
    window.TEST_REPORT[key] = { failed: run.failed, total: run.total };
    caught.push({ ok: run.failed > 0, text: mutant.label });
  }

  panel("Эвдэрсэн хувилбаруудыг барьсан эсэх", caught.every((c) => c.ok) ? "ok" : "bad", caught);

  useImplementation({});
  document.body.dataset.ready = "1";
})();

